#!/bin/sh
#
# smoke.sh -- GNU coreutils 5.2.1 acceptance, ON THE BOX, as root.
#
#     sh tests/smoke.sh [bindir]          (default /opt/amix/bin)
#
# Every check reads OUTPUT or FILES, not only an exit status; expected digests
# were computed on the host over the same awk-generated bytes.  1992 Bourne
# shell: backticks, expr, no grep -q, no $(...), no `!'.  Result lines start
# with "RES "; the last is "RES smoke PASS" or "RES smoke FAIL <n>".

B=${1:-/opt/amix/bin}
fails=0
ok()  { echo "RES ok   $*"; }
bad() { echo "RES FAIL $*"; fails=`expr $fails + 1`; }
has() { grep "$2" "$1" > /dev/null 2>&1; }
# eq <what> <got> <want>
eq()  { if [ "$2" = "$3" ]; then ok "$1"; else bad "$1: got '$2' want '$3'"; fi; }
flat() { tr '\012' ' ' < "$1" | sed 's/ $//'; }

n=0
for p in `ls $B`; do n=`expr $n + 1`; done
echo "== $n files in $B"
rm -rf csmoke; mkdir csmoke; cd csmoke || exit 1
$B/ls --version | sed -n 1p

# --- 1. content checksums: the box had none (registry/coreutils.yaml) --------
awk 'BEGIN { for (i = 1; i <= 20000; i++) printf "%05d line of text %d\n", i, i * 13 }' > big
eq "fixture size" "`$B/wc -c < big | tr -d ' '`" 511456
eq "md5sum of 511456 bytes" "`$B/md5sum big`" "3a7bd6cba8abaa05eca271c15ac87af4  big"
eq "sha1sum of 511456 bytes" "`$B/sha1sum big`" "5dd6176a640190b64839b4b0a9c50dfe126ffc7b  big"
eq "cksum (POSIX CRC)" "`$B/cksum big`" "1756924139 511456 big"
eq "md5sum 'abc'" "`echo abc | tr -d '\012' | $B/md5sum`" "900150983cd24fb0d6963f7d28e17f72  -"
eq "sha1sum 'abc'" "`echo abc | tr -d '\012' | $B/sha1sum`" "a9993e364706816aba3e25717850c26c9cd0d89d  -"
eq "md5sum of nothing" "`$B/md5sum < /dev/null`" "d41d8cd98f00b204e9800998ecf8427e  -"
$B/md5sum big > big.md5; $B/md5sum -c big.md5 > c.out 2>&1; rc=$?
[ $rc -eq 0 ] && has c.out '^big: OK$' && ok "md5sum -c verifies" || bad "md5sum -c rc=$rc: `flat c.out`"
echo x >> big; $B/md5sum -c big.md5 > c2.out 2>&1; rc=$?
[ $rc -eq 1 ] && has c2.out 'FAILED' && ok "md5sum -c catches a changed file" || bad "md5sum -c changed rc=$rc"
eq "sum -r agrees with the stock sum -r" "`$B/sum -r big | awk '{print $1+0}'`" "`/usr/bin/sum -r big | awk '{print $1+0}'`"

# --- 2. D3: names for uids/gids (getpwnam/getgrnam in the executable) ---------
eq "id -un" "`$B/id -un`" root
eq "whoami" "`$B/whoami`" root
$B/id > id.out; has id.out '^uid=0(root) gid=[0-9]*([a-z]*)' && ok "id: `cat id.out`" || bad "id: `cat id.out`"
g=`$B/groups`; [ -n "$g" ] && ok "groups (script over id -Gn): $g" || bad "groups empty"
echo f > owned; $B/chown bin:bin owned; rc=$?
eq "chown bin:bin, ls -l owner/group (rc $rc)" "`$B/ls -l owned | awk '{print $3, $4}'`" "bin bin"
eq "ls -ln numeric" "`$B/ls -ln owned | awk '{print $3}'`" "`grep '^bin:' /etc/passwd | awk -F: '{print $3}'`"
$B/chgrp sys owned; eq "chgrp sys" "`$B/ls -l owned | awk '{print $4}'`" sys
eq "stat %U:%G" "`$B/stat -c %U:%G owned`" "bin:sys"
$B/ls -l /etc/passwd /etc/group > lsl.out
has lsl.out ' root ' && ok "ls -l /etc/passwd /etc/group names owners" || bad "ls -l: `flat lsl.out`"

# --- 3. files: cp/mv/rm/ln, modes, symlinks (lstat), times ---------------------
mkdir -p d1/sub; echo one > d1/a; echo two > d1/sub/b; chmod 640 d1/a
$B/touch -d '2001-02-03 04:05:06' d1/a
$B/cp -rp d1 d2; rc=$?
eq "cp -rp copies the tree (rc $rc)" "`cat d2/sub/b`" two
eq "cp -p keeps the mode" "`$B/ls -l d2/a | awk '{print $1}'`" "-rw-r-----"
eq "cp -p keeps the mtime (touch -d)" "`$B/date -r d2/a '+%Y-%m-%d %H:%M:%S'`" "2001-02-03 04:05:06"
$B/mv d2 d3; [ -d d3 ] && [ ! -d d2 ] && ok "mv a directory" || bad "mv"
$B/ln -s d1/a lnk
eq "readlink" "`$B/readlink lnk`" d1/a
$B/ls -l lnk > lnk.out; has lnk.out 'lnk -> d1/a$' && ok "ls -l shows the symlink (lstat)" || bad "ls -l lnk: `flat lnk.out`"
eq "stat -c %F on the symlink" "`$B/stat -c %F lnk`" "symbolic link"
$B/rm -rf d3 lnk; [ ! -d d3 ] && $B/test ! -h lnk && ok "rm -rf" || bad "rm -rf"
$B/mkdir -p p/q/r; [ -d p/q/r ] && ok "mkdir -p" || bad "mkdir -p"
$B/install -m 751 d1/a p/inst; eq "install -m 751" "`$B/ls -l p/inst | awk '{print $1}'`" "-rwxr-x--x"
$B/mkfifo ff; $B/test -p ff && ok "mkfifo" || bad "mkfifo"
$B/link d1/a hl; eq "link: 2 links" "`$B/stat -c %h d1/a`" 2
$B/unlink hl; eq "unlink: 1 link" "`$B/stat -c %h d1/a`" 1
cp big shredme; $B/shred -u shredme; [ ! -f shredme ] && ok "shred -u" || bad "shred -u"
$B/ls -la p > la.out; has la.out '^total' && has la.out ' q$' && ok "ls -la" || bad "ls -la"
eq "dir == ls -C" "`$B/dir d1`" "`$B/ls -C -b d1`"
$B/dircolors -b > dc.out; has dc.out '^LS_COLORS=' && ok "dircolors -b" || bad "dircolors"

# --- 4. file systems: df (getmntent), du, stat -f (statvfs) --------------------
$B/df / > df.out; rc=$?
[ $rc -eq 0 ] && has df.out ' /$' && ok "df /: `sed -n 2p df.out`" || bad "df rc=$rc: `flat df.out`"
$B/df -k > dfk.out; [ `wc -l < dfk.out` -ge 2 ] && ok "df -k lists `expr \`wc -l < dfk.out\` - 1` file system(s)" || bad "df -k"
eq "du -sk on 511457 bytes" "`$B/du -sk big | awk '{print ($1 >= 499 && $1 <= 520) ? "ok" : $1}'`" ok
$B/stat -f / > sf.out; rc=$?
[ $rc -eq 0 ] && has sf.out 'Type: ' && ok "stat -f / (statvfs): `sed -n 's/.*\(Type: [a-zA-Z0-9]*\).*/\1/p' sf.out`" || bad "stat -f rc=$rc: `flat sf.out`"

# --- 5. text --------------------------------------------------------------------
awk 'BEGIN { for (i = 30; i >= 1; i--) print i }' > nums
eq "sort -n" "`$B/sort -n nums | $B/head -3 | tr '\012' ' '`" "1 2 3 "
eq "sort -S 32k (temp files, mkstemp) == stock sort" "`$B/sort -S 32k big | $B/md5sum`" "`/usr/bin/sort big | $B/md5sum`"
eq "sort -t: -k3,3n" "`$B/printf 'a:x:3\nb:y:1\nc:z:2\n' | $B/sort -t: -k3,3n | $B/cut -d: -f1 | tr '\012' ' '`" "b c a "
eq "head -n 2 / tail -n 1" "`$B/head -n 2 nums | $B/tail -n 1`" 29
eq "tail -c 6" "`$B/tail -c 6 nums | tr '\012' ' '`" "3 2 1 "
eq "wc -l -w -c" "`$B/wc -l -w -c < nums | tr -s ' ' | sed 's/^ //'`" "30 30 81"
eq "tr a-z A-Z" "`echo coreutils | $B/tr a-z A-Z`" COREUTILS
eq "cut -d: -f1 of root's passwd line" "`grep '^root:' /etc/passwd | $B/cut -d: -f1`" root
eq "uniq -c" "`(echo a; echo a; echo b) | $B/uniq -c | tr -s ' ' | tr '\012' '|'`" " 2 a| 1 b|"
eq "tac" "`(echo 1; echo 2; echo 3) | $B/tac | tr '\012' ' '`" "3 2 1 "
eq "nl" "`echo x | $B/nl | tr -s ' \011' '  '`" " 1 x"
(echo 1 a; echo 2 b) > j1; (echo 1 X; echo 2 Y) > j2
eq "join" "`$B/join j1 j2 | tr '\012' '|'`" "1 a X|2 b Y|"
eq "paste -d," "`$B/paste -d, j1 j2 | $B/head -1`" "1 a,1 X"
eq "comm -12" "`(echo a; echo b) > c1; (echo b; echo c) > c2; $B/comm -12 c1 c2`" b
$B/split -l 10000 big part_; eq "split -l 10000 (20001 lines)" "`ls part_* | wc -l | tr -d ' '`" 3
$B/csplit -s nums 10 > /dev/null; eq "csplit" "`cat xx00 | wc -l | tr -d ' '`" 9
eq "od -c" "`echo ab | $B/od -c | sed -n 1p | tr -s ' '`" "0000000 a b \n"
eq "fold -w 3" "`echo abcdef | $B/fold -w 3 | tr '\012' ' '`" "abc def "
eq "expand" "`echo 'a	b' | $B/expand | tr ' ' '.'`" "a.......b"
eq "unexpand -a" "`echo 'a       b' | $B/unexpand -a | $B/od -c | sed -n 1p | tr -s ' '`" "0000000 a \t b \n"
eq "tsort" "`(echo a b; echo b c) | $B/tsort | tr '\012' ' '`" "a b c "
eq "fmt -w 10" "`echo 'aaa bbb ccc ddd' | $B/fmt -w 10 | wc -l | tr -d ' '`" 2
eq "pr -t -2" "`$B/seq 4 | $B/pr -t -2 -w 20 | sed -n 1p | tr -s ' \011' '  ' | sed 's/ *$//'`" "1 3"
eq "ptx" "`echo 'hello world' | $B/ptx | wc -l | tr -d ' '`" 2
eq "tee" "`echo t | $B/tee teeout`/`cat teeout`" "t/t"

# --- 6. numbers and time: factor (64-bit), seq (patch 06), printf, sleep, date --
eq "factor (64-bit operand)" "`$B/factor 1001 4294967291 600851475143 | tr '\012' '|'`" "1001: 7 11 13|4294967291: 4294967291|600851475143: 71 839 1471 6857|"
eq "seq -w 8 10" "`$B/seq -w 8 10 | tr '\012' ' '`" "08 09 10 "
eq "seq 5 -2 -3" "`$B/seq 5 -2 -3 | tr '\012' ' '`" "5 3 1 -1 -3 "
eq "seq 0.5 0.5 2 (%g)" "`$B/seq 0.5 0.5 2 | tr '\012' ' '`" "0.5 1 1.5 2 "
eq "printf %5.2f %d %s" "`$B/printf '%5.2f|%d|%s' 3.14159 42 x`" " 3.14|42|x"
eq "expr" "`$B/expr 6 \* 7`" 42
t0=`$B/date +%s`; $B/sleep 2; t1=`$B/date +%s`
d=`expr $t1 - $t0`; [ $d -ge 2 ] && [ $d -le 4 ] && ok "sleep 2 took $d s (nanosleep -> select)" || bad "sleep 2 took $d s"
eq "date -u -d @0" "`$B/date -u -d '1970-01-01 00:00:00 UTC' +%s`" 0
eq "date -d parse" "`$B/date -u -d '2026-10-29 12:34:56 UTC' '+%Y %j %H:%M'`" "2026 302 12:34"

# --- 7. the rest --------------------------------------------------------------------
eq "basename/dirname" "`$B/basename /a/b/c.txt .txt`/`$B/dirname /a/b/c.txt`" "c//a/b"
eq "echo -n" "`$B/echo -n x; $B/echo y`" xy
eq "env -i" "`$B/env -i FOO=bar $B/printenv FOO`" bar
eq "test / [" "`$B/test -d / && $B/[ 1 -lt 2 ] && echo y`" y
eq "true/false" "`$B/true; echo $?``$B/false; echo $?`" "01"
eq "yes | head -2" "`$B/yes | $B/head -2 | tr '\012' ' '`" "y y "
eq "pathchk" "`$B/pathchk -p abc; echo $?`" 0
eq "pwd" "`$B/pwd`" "`/bin/pwd`"
eq "dd 4 KB" "`$B/dd if=/dev/zero bs=1024 count=4 2>/dev/null | $B/wc -c | tr -d ' '`" 4096
eq "uname -s" "`$B/uname -s`" "`/usr/bin/uname -s`"
eq "hostname" "`$B/hostname`" "`/usr/bin/uname -n`"
eq "nice -n 5 nice" "`$B/nice -n 5 $B/nice`" 5
eq "nohup" "`$B/nohup echo n 2>/dev/null`" n
$B/kill -l > kl.out; has kl.out 'HUP' && ok "kill -l" || bad "kill -l: `flat kl.out`"
$B/tty > /dev/null < /dev/null; eq "tty on a non-tty: rc 1" "$?" 1
$B/sync && ok "sync" || bad "sync"
$B/who > who.out 2>&1; rc=$?; [ $rc -eq 0 ] && ok "who rc 0 (`wc -l < who.out | tr -d ' '` session(s))" || bad "who rc=$rc: `flat who.out`"
$B/users > /dev/null 2>&1; eq "users rc" "$?" 0
$B/pinky > /dev/null 2>&1; eq "pinky rc" "$?" 0
$B/logname > /dev/null 2>&1; rc=$?; ok "logname rc $rc (no login tty under the harness is fine)"
$B/stty -a < /dev/null > /dev/null 2>&1; rc=$?; [ $rc -ne 0 ] && ok "stty on a non-tty refuses (rc $rc)" || bad "stty on /dev/null rc 0"

cd ..
if [ $fails -eq 0 ]; then echo "RES smoke PASS"; else echo "RES smoke FAIL $fails"; fi
[ $fails -eq 0 ]
